import 'dart:async';

Future<T> retry<T>(
  Future<T> Function() action, {
  int attempts = 3,
  Duration delay = const Duration(milliseconds: 200),
}) async {
  var wait = delay;
  for (var attempt = 1; ; attempt++) {
    try {
      return await action();
    } catch (error, stackTrace) {
      if (attempt >= attempts) {
        Error.throwWithStackTrace(error, stackTrace);
      }
      await Future<void>.delayed(wait);
      wait *= 2;
    }
  }
}

