import 'dart:async';
import 'package:flutter/material.dart';

class TickerView extends StatefulWidget {
  const TickerView({super.key, required this.source});

  final Stream<int> source;

  @override
  State<TickerView> createState() => _TickerViewState();
}

class _TickerViewState extends State<TickerView> {
  StreamSubscription<int>? _subscription;
  int? _value;
  Object? _error;

  @override
  void initState() {
    super.initState();
    _subscribe();
  }

  @override
  void didUpdateWidget(covariant TickerView oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.source != widget.source) {
      _unsubscribe();
      setState(() {
        _value = null;
        _error = null;
      });
      _subscribe();
    }
  }

  @override
  void dispose() {
    _unsubscribe();
    super.dispose();
  }

  void _subscribe() {
    _subscription = widget.source.listen(
      (value) => setState(() {
        _value = value;
        _error = null;
      }),
      onError: (Object error) => setState(() {
        _error = error;
        _value = null;
      }),
    );
  }

  void _unsubscribe() {
    _subscription?.cancel();
    _subscription = null;
  }

  @override
  Widget build(BuildContext context) {
    if (_error != null) return Text('$_error');
    return Text(_value?.toString() ?? '—');
  }
}

