import Foundation
import UIKit

actor ImageLoader {
    private enum Entry {
        case inFlight(Task<UIImage, Error>)
        case ready(UIImage)
    }

    private var cache: [URL: Entry] = [:]
    private let download: (URL) async throws -> UIImage

    init(download: @escaping (URL) async throws -> UIImage) {
        self.download = download
    }

    func image(for url: URL) async throws -> UIImage {
        switch cache[url] {
        case .ready(let image):
            return image
        case .inFlight(let task):
            return try await task.value
        case nil:
            break
        }

        let task = Task { try await download(url) }
        cache[url] = .inFlight(task)

        do {
            let image = try await task.value
            cache[url] = .ready(image)
            return image
        } catch {
            // Don't cache a failure — the next caller gets a fresh attempt.
            cache[url] = nil
            throw error
        }
    }
}

