import UIKit

final class ProfileRowView: UIView {
    let avatarView = UIImageView()
    let titleLabel = UILabel()
    let subtitleLabel = UILabel()

    override init(frame: CGRect) {
        super.init(frame: frame)
        setUp()
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

    private func setUp() {
        let text = UIStackView(arrangedSubviews: [titleLabel, subtitleLabel])
        text.axis = .vertical
        text.spacing = 2

        for view in [avatarView, text] {
            view.translatesAutoresizingMaskIntoConstraints = false
            addSubview(view)
        }

        avatarView.layer.cornerRadius = 22
        avatarView.clipsToBounds = true
        avatarView.contentMode = .scaleAspectFill

        titleLabel.numberOfLines = 1
        titleLabel.lineBreakMode = .byTruncatingTail
        subtitleLabel.numberOfLines = 1
        subtitleLabel.textColor = .secondaryLabel

        // The labels must yield before the avatar does, or a long title
        // stretches the row instead of truncating.
        titleLabel.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)

        NSLayoutConstraint.activate([
            avatarView.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 12),
            avatarView.centerYAnchor.constraint(equalTo: centerYAnchor),
            avatarView.widthAnchor.constraint(equalToConstant: 44),
            avatarView.heightAnchor.constraint(equalToConstant: 44),

            text.leadingAnchor.constraint(equalTo: avatarView.trailingAnchor, constant: 12),
            text.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -12),
            text.topAnchor.constraint(equalTo: topAnchor, constant: 12),
            text.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -12),

            avatarView.topAnchor.constraint(greaterThanOrEqualTo: topAnchor, constant: 12),
            bottomAnchor.constraint(greaterThanOrEqualTo: avatarView.bottomAnchor, constant: 12),
        ])
    }
}

