fun <T> Iterable<T>.splitWhen(predicate: (T) -> Boolean): List<List<T>> {
    val groups = mutableListOf<List<T>>()
    var current = mutableListOf<T>()

    for (element in this) {
        if (predicate(element) && current.isNotEmpty()) {
            groups += current
            current = mutableListOf()
        }
        current += element
    }
    if (current.isNotEmpty()) groups += current

    return groups
}

fun main() {
    println(listOf(1, 2, 10, 3, 10, 20).splitWhen { it >= 10 })
}

