// commonMain code takes the store as a dependency; it never constructs one.
class SessionRepository(private val store: KeyValueStore) {
    var token: String?
        get() = store.get("token")
        set(value) { store.put("token", value ?: "") }
}

// ── androidMain/kotlin/storage/KeyValueStore.android.kt ─────────────────
package storage

import android.content.Context
import android.content.SharedPreferences

actual class KeyValueStore(private val prefs: SharedPreferences) {
    actual fun get(key: String): String? = prefs.getString(key, null)

    actual fun put(key: String, value: String) {
        prefs.edit().putString(key, value).apply()
    }
}

// The Context stays on the Android side of the boundary: the app module
// builds the store and hands it to the shared code.
fun KeyValueStore(context: Context): KeyValueStore =
    KeyValueStore(context.getSharedPreferences("app", Context.MODE_PRIVATE))

